#include "RadarTargets.h"
void RadarTargets::clear(){for(auto& t:t_)t=TrackedTarget();}
void RadarTargets::update(const LD2450Target in[3],uint32_t now){for(int i=0;i<3;i++){TrackedTarget& t=t_[i];if(!in[i].valid)continue;bool fresh=!t.active||(now-t.lastSeenMs)>TARGET_TIMEOUT_MS;t.rawX=in[i].x;t.rawY=in[i].y;t.speed=in[i].speed;t.res=in[i].res;t.rawDist=in[i].dist;if(fresh){t.sx=in[i].x;t.sy=in[i].y;t.trailCount=0;t.trailHead=0;}else{t.sx+=TARGET_SMOOTH*(in[i].x-t.sx);t.sy+=TARGET_SMOOTH*(in[i].y-t.sy);}t.trail[t.trailHead]={(int16_t)t.sx,(int16_t)t.sy};t.trailHead=(t.trailHead+1)%TRAIL_LEN;if(t.trailCount<TRAIL_LEN)t.trailCount++;t.active=true;t.lastSeenMs=now;}}
void RadarTargets::expire(uint32_t now){for(auto& t:t_)if(t.active&&(now-t.lastSeenMs)>TARGET_TIMEOUT_MS){t.active=false;t.trailCount=0;}}
TargetState RadarTargets::stateOf(uint8_t i,uint32_t now)const{const TrackedTarget& t=t_[i];if(!t.active)return TS_NONE;uint32_t age=now-t.lastSeenMs;if(age>TARGET_TIMEOUT_MS)return TS_NONE;return age<=TARGET_HOLD_MS?TS_LIVE:TS_HOLD;}
uint8_t RadarTargets::liveCount(uint32_t now)const{uint8_t n=0;for(uint8_t i=0;i<3;i++)if(stateOf(i,now)==TS_LIVE)n++;return n;}
int8_t RadarTargets::nearest(uint32_t now)const{int8_t best=-1;float bd=1e9f;for(uint8_t i=0;i<3;i++)if(stateOf(i,now)==TS_LIVE&&t_[i].rawDist<bd){bd=t_[i].rawDist;best=i;}return best;}
bool RadarTargets::trailAt(const TrackedTarget& t,uint8_t k,TrailPoint& out){if(k>=t.trailCount)return false;int idx=((int)t.trailHead-1-(int)k+2*TRAIL_LEN)%TRAIL_LEN;out=t.trail[idx];return true;}